head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.gLinkApplSeq;
scwin.gLinkListStatCd;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no; // 세션정보 	
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

scwin.gPROCS_CD = '';
scwin.V_PROCS_CD_2 = '2'; //검토
scwin.V_PROCS_CD_3 = '3'; //승인
scwin.V_PROCS_CD_4 = '4'; //거부

scwin.vScrenID = "ULDSTF33011.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// 처리버튼 생성여부 
scwin.fn_showProcButton = function(pProcsDepCd, pLinkListStatCd) {
    scwin.gLinkListStatCd = pLinkListStatCd;
    btn_Revwr.src = "../img/btn_study_d.gif";
    btn_Revwr.setDisabled(true);
    btn_Approve.src = "../img/btn_approval_d.gif";
    btn_Approve.setDisabled(true);
    btn_Reject.src = "../img/btn_reject2_dis.gif";
    btn_Reject.setDisabled(true);
    $c.stf.showObj(panel_Button, false);

    //alert(gDutyYn+","+gDutyChrg+","+gDepCd+","+pProcsDepCd);

    if (scwin.gLinkApplSeq != '') {
        //1:미처리,2:검토,3:승인,4:거부
        if (scwin.gLinkListStatCd == '1' || scwin.gLinkListStatCd == '2') {
            $c.stf.showObj(panel_Button, true);
            if (scwin.gLinkListStatCd == '1') {
                if (scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y' || scwin.gDepCd == pProcsDepCd) {
                    // 팀장 및 당번 권한일때만 보임
                    btn_Revwr.src = "../img/btn_study.gif";
                    btn_Revwr.setDisabled(false);
                    btn_Reject.src = "../img/btn_reject2.gif";
                    btn_Reject.setDisabled(false);
                }
            } else if (scwin.gLinkListStatCd == '2') {
                // 팀장 및 당번 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
                if ((scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') || (scwin.gJobTitle == '09' && scwin.gDepCd == pProcsDepCd)) {
                    btn_Approve.src = "../img/btn_approval.gif";
                    btn_Approve.setDisabled(false);
                    btn_Reject.src = "../img/btn_reject2.gif";
                    btn_Reject.setDisabled(false);
                }
            }
        }
    }
};
scwin.fn_GetParentValue = function() {
    scwin.gLinkApplSeq = $c.frame.path("../").scwin.gLinkApplSeq;
};
scwin.fn_Init = function() {
    var gMsg = "" + "① 지주회사의 신청내용을 근거로 하여서만 상장자회사의 수시공시 내용이 지주회사 종목공시에 연계하여  \n" + "    공표되므로, 연계공시 신청서 작성시 착오가 발생하지 않도록 주의하시기 바라며, 변동사실＊ 발생시에는  \n" + "    동 사실을 즉시 정정하여 신청서를 제출하여야 함  \n" + "    ＊ 변동사실 \n" + "       가. 상장 여부의 변동, 상장된 증권시장의 이동 등 \n" + "       나. 지주회사가 소유하고 있는 상장자회사 주식의 최근 사업연도말 재무제표상 가액이 지주회사의  \n" + "            최근 사업연도말 자산총액의 10% 이상․미만 등  \n" + "② 상장자회사의 변동사실을 거래소에 미신고함으로써 발생하는 모든 책임은 지주회사에게 있음\n" + "③ 정정공시의 경우에는 연계공시 적용일 이후의 공시내용이 정정되는 경우에 한하여만 연계공표되므로 \n" + "    적용일 이전의 상장자회사가 제출한 수시공시 내용에 대한 정정공시에 대하여는 지주회사가 이를 \n" + "    별도로 제출하여야 함 \n" + "④ 지주회사-자회사간 상장된 증권시장이 상이한 경우에는 자회사 공시내용의 지주회사 연계공표시 자회사가 \n" + "     상장된 증권시장을 기준으로 생성됨을 원칙으로 함 \n" + "⑤ 연계공시 신청에 의하여 상장자회사의 수시공시 내용이 지주회사의 별도 공시제출없이 증권시장에 공표된 경우, \n" + "    연계공시 내용에 대한 지주회사의 공시내용 정정을 위한 수정․편집 기능은 제공하지 않음 \n" + "⑥ 연계공시 신청에 의하여 상장자회사의 수시공시 내용이 지주회사의 별도 공시제출없이 증권시장에 공표된 경우, \n" + "    상장자회사가 수시공시 내용을 철회(또는 삭제)한 경우에 한하여만 지주회사의 연계공시 내용에 대한 \n" + "    철회(또는 삭제)가 가능함";
    txa_Noti.Text = gMsg;
};
scwin.fn_read_sync = function() {
    var url = "/LnkDisclsApplCorp.do?method=selectLnkDisclsApplCorp" + "&SEARCH_TYP=APPL_READ" + "&LNK_DISCLS_APPL_SEQ=" + scwin.gLinkApplSeq;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Item.DataID = encodeURI(url);
    dts_Item.reset();
};
scwin.fn_getProcsSate = function(gProcsStatCd) {
    // 처리상태 조회하기
    var url = "/LnkDisclsApplCorp.do?method=selectLnkDisclsApplCorp" + "&SEARCH_TYP=CHK_PROCS_STAT" + "&LNK_DISCLS_APPL_SEQ=" + scwin.gLinkApplSeq;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Check.DataID = encodeURI(url);
    dts_Check.reset();
    var vPROCS_STAT_CD = dts_Check.getCellData(1, "LNK_DISCLS_PROCS_STAT_CD");
    var vPROCS_STAT_NM = dts_Check.getCellData(1, "LNK_DISCLS_PROCS_STAT_NM");
    if (gProcsStatCd == vPROCS_STAT_CD) {
        $c.win.alert("신청건은  이미 [" + vPROCS_STAT_NM + "] 처리가 되었습니다.");
        //fn_CloseParentReload();
        return false;
    }
    if (gProcsStatCd != scwin.V_PROCS_CD_4) {
        // 중복처리 체크
        var url = "/LnkDisclsApplCorp.do?method=selectLnkDisclsApplCorp" + "&SEARCH_TYP=CHK_DOUBLE_PROCS" + "&LNK_DISCLS_APPL_SEQ=" + scwin.gLinkApplSeq;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Check.DataID = encodeURI(url);
        dts_Check.reset();
        var V_LNK_DISCLS_APPL_TP_NM = dts_Check.getCellData(1, "LNK_DISCLS_APPL_TP_NM");
        var V_LNK_DISCLS_APPL_DD = dts_Check.getCellData(1, "LNK_DISCLS_APPL_DD");
        if (dts_Check.getTotalRow() > 0) {
            $c.win.alert("선택한 자회사는  이미 [" + V_LNK_DISCLS_APPL_TP_NM + "] 신청건으로 승인상태[연계공시적용일(" + V_LNK_DISCLS_APPL_DD + ")] 에 있어 처리 할 수 없습니다.");
            return false;
        }

        // 법인상태 조회하기
        var url = "/LnkDisclsApplCorp.do?method=selectLnkDisclsApplCorp" + "&SEARCH_TYP=CHK_CORP_STAT" + "&LNK_DISCLS_APPL_SEQ=" + scwin.gLinkApplSeq;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Check.DataID = encodeURI(url);
        dts_Check.reset();
        var vHdcomLstStatCd = dts_Check.getCellData(1, "HDCOM_LIST_STAT_CD");
        var vSumcomLstStatCd = dts_Check.getCellData(1, "SUBCOM_LIST_STAT_CD");
        var vLnkDisclsSubmitCorpYn = dts_Check.getCellData(1, "LNK_DISCLS_SUBMIT_CORP_YN");
        if (vHdcomLstStatCd != 'Y') {
            $c.win.alert("지주회사는 상장법인이 아니므로  처리할 수 없습니다.");
            return false;
        }
        if (vSumcomLstStatCd != 'Y') {
            $c.win.alert("자회사는 상장법인이 아니므로  처리할 수 없습니다.");
            return false;
        }
        if (dts_Item.getCellData(1, "LNK_DISCLS_APPL_TP_CD") == '1') {
            if (vLnkDisclsSubmitCorpYn == 'Y') {
                $c.win.alert("신청자회사는 이미 연계공시 등록법인이므로  처리할 수 없습니다.");
                return false;
            }
        }
    }
    return true;
};
scwin.fn_Save = function(pType) {
    if (scwin.gLinkApplSeq == "") {
        $c.win.alert("[대상]을 선택하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(edt_LNK_DISCLS_APPL_DD) == "") {
        $c.win.alert("[연계공시적용일]을 입력하세요.");
        edt_LNK_DISCLS_APPL_DD.focus();
        return false;
    }
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (vCurDate >= $c.stf.getObjectValue(edt_LNK_DISCLS_APPL_DD)) {
        $c.win.alert("[연계공시적용일]을 현재일이후로 입력하세요.");
        edt_LNK_DISCLS_APPL_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_REJ_RSN) != "") {
        $c.win.alert("거부시에만 [거부사유]를 입력하세요.");
        txb_REJ_RSN.focus();
        return false;
    }
    var gMSG = '';
    if (pType == 'R') {
        scwin.gPROCS_CD = scwin.V_PROCS_CD_2;
        gMSG = '검토';
    } else if (pType == 'A') {
        scwin.gPROCS_CD = scwin.V_PROCS_CD_3;
        gMSG = '승인';
    }
    var rtn = confirm(gMSG + '처리 하시겠습니까?');
    if (rtn == 1) {
        if (scwin.fn_getProcsSate(scwin.gPROCS_CD) == false) {
            return false;
        } else {
            trs_Approve.Action = "/LnkDisclsApplCorp.do?method=approveLnkDisclsApplCorp" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Approve.KeyName = "toinb_dataid4";
            trs_Approve.KeyValue = "JSP(I:pInput=dts_Item)";
            trs_Approve.Parameters = "LNK_DISCLS_APPL_SEQ=" + scwin.gLinkApplSeq + ",PROCS_CD=" + scwin.gPROCS_CD + ",LNK_DISCLS_APPL_DD=" + $c.stf.getObjectValue(edt_LNK_DISCLS_APPL_DD) + ",EMP_NO=" + js_emp_no;
            trs_Approve.Post();
        }
    }
};
scwin.fn_Revwr = function() {
    scwin.fn_Save('R');
};
scwin.fn_Approve = function() {
    scwin.fn_Save('A');
};
scwin.fn_Reject = function() {
    if (scwin.gLinkApplSeq == "") {
        $c.win.alert("[대상]을 선택하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_REJ_RSN) == "") {
        $c.win.alert("[거부사유]를 입력하세요.");
        txb_REJ_RSN.focus();
        return false;
    }
    scwin.gPROCS_CD = scwin.V_PROCS_CD_4;
    var rtn = confirm('거부처리 하시겠습니까?');
    if (rtn == 1) {
        if (scwin.fn_getProcsSate(scwin.gPROCS_CD) == false) {
            return false;
        } else {
            trs_Approve.Action = "/LnkDisclsApplCorp.do?method=approveLnkDisclsApplCorp" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Approve.KeyName = "toinb_dataid4";
            trs_Approve.KeyValue = "JSP(I:pInput=dts_Item)";
            trs_Approve.Parameters = "LNK_DISCLS_APPL_SEQ=" + scwin.gLinkApplSeq + ",PROCS_CD=" + scwin.V_PROCS_CD_4 + ",LNK_DISCLS_APPL_DD=" + $c.stf.getObjectValue(edt_LNK_DISCLS_APPL_DD) + ",EMP_NO=" + js_emp_no + ",REJ_RSN=" + $c.stf.getObjectValue(txb_REJ_RSN);
            trs_Approve.Post();
        }
    }
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_Check_OnLoadError = function() {
    $c.stf.alert_error(dts_Check);
};
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    scwin.fn_showProcButton(dts_Item.getCellData(1, "HDCOM_DEP_CD"), dts_Item.getCellData(1, "LNK_DISCLS_PROCS_STAT_CD"));
    $c.stf.showObj(panel_BF_OVR10PCT_YN, false);
    $c.stf.showObj(panel_AF_OVR10PCT_YN, false);
    if (dts_Item.getCellData(1, "LNK_DISCLS_APPL_TP_CD") == '2') {
        $c.stf.showObj(panel_BF_OVR10PCT_YN, true);
        $c.stf.showObj(panel_AF_OVR10PCT_YN, true);
    }
};
scwin.img_LNK_DISCLS_APPL_DD_onclick = function() {
    popUpCalendar2(edt_LNK_DISCLS_APPL_DD);
};
scwin.trs_Approve_OnSuccess = function() {
    $c.win.alert('정상처리되었습니다');
    scwin.fn_read_sync();
    $c.frame.path("../").fn_list_sync();
};
scwin.trs_Approve_OnFail = function() {
    $c.win.alert('처리가 실패하였습니다');
    $c.win.alert(trs_Approve.ErrorMsg);
};
scwin.btn_Revwr_onclick = function() {
    scwin.fn_Revwr();
};
scwin.btn_Approve_onclick = function() {
    scwin.fn_Approve();
};
scwin.btn_Reject_onclick = function() {
    scwin.fn_Reject();
};
scwin.btn_Close_onclick = async function() {
    $c.frame.path("../").fn_list_sync();
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.fn_GetParentValue();
    scwin.fn_Init();
    scwin.fn_read_sync();
};
